use crate::Blake3DigestV1;
const TAG: &[u8] = b"worldstream/operational-mmr/v1\0";
fn h(parts:&[&[u8]])->Blake3DigestV1 { let mut x=blake3::Hasher::new(); x.update(TAG); for p in parts { x.update(&(p.len() as u64).to_be_bytes()); x.update(p); } Blake3DigestV1::from_bytes(*x.finalize().as_bytes()) }
#[derive(Clone,Debug)] pub struct OperationalMmrV1 { domain:String, leaves:Vec<Blake3DigestV1> }
#[derive(Clone,Debug)] pub struct OperationalMmrProofV1 { pub domain:String,pub index:u64,pub leaf:Blake3DigestV1,pub siblings:Vec<(Blake3DigestV1,bool)> }
impl OperationalMmrV1 { pub fn new(domain:impl Into<String>)->Self{Self{domain:domain.into(),leaves:vec![]}} pub fn append(&mut self, bytes:&[u8]) { self.leaves.push(h(&[self.domain.as_bytes(),bytes])); } pub fn root(&self)->Blake3DigestV1 { self.leaves.iter().fold(h(&[self.domain.as_bytes(),b"empty"]),|a,b|h(&[self.domain.as_bytes(),a.as_bytes(),b.as_bytes()])) } pub fn prove(&self,index:usize)->Option<OperationalMmrProofV1>{let leaf=self.leaves.get(index)?.clone();let mut siblings=vec![];let mut acc=h(&[self.domain.as_bytes(),b"empty"]);for (i,v) in self.leaves.iter().enumerate(){if i<index {acc=h(&[self.domain.as_bytes(),acc.as_bytes(),v.as_bytes()]);} else if i>index {siblings.push((v.clone(),false));}} Some(OperationalMmrProofV1{domain:self.domain.clone(),index:index as u64,leaf,siblings})} }
impl OperationalMmrProofV1 { pub fn verify(&self, root:&Blake3DigestV1)->bool { let mut acc=h(&[self.domain.as_bytes(),b"empty"]); acc=h(&[self.domain.as_bytes(),acc.as_bytes(),self.leaf.as_bytes()]); for (s,_) in &self.siblings {acc=h(&[self.domain.as_bytes(),acc.as_bytes(),s.as_bytes()]);} &acc==root } }
